input.new_string:
    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    #[test]
    fn mismatched_quotes_are_preserved() {
        let content = "A=\"value'\nB='value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("A"), Some(&"\"value'".to_string()));
        assert_eq!(vars.get("B"), Some(&"'value\"".to_string()));
    }

    #[test]
    fn empty_quoted_strings() {
        let content = "DOUBLE=\"\"\nSINGLE=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("DOUBLE"), Some(&String::new()));
        assert_eq!(vars.get("SINGLE"), Some(&String::new()));
    }

    #[test]
    fn single_quote_character_as_value() {
        let content = "DQ=\"\nSQ='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("DQ"), Some(&"\"".to_string()));
        assert_eq!(vars.get("SQ"), Some(&"'".to_string()));
    }

    #[test]
    fn escaped_characters_in_double_quotes() {
        let content = r#"A="hello\"world"
B="line\nnewline"
C="back\\slash"
D="tab\there""#;
        let vars = EnvFileParser::parse(content).unwrap();
        // Parser does not interpret escape sequences; backslashes are literal
        assert_eq!(vars.get("A"), Some(&r#"hello\"world"#.to_string()));
        assert_eq!(vars.get("B"), Some(&r"line\nnewline".to_string()));
        assert_eq!(vars.get("C"), Some(&r"back\\slash".to_string()));
        assert_eq!(vars.get("D"), Some(&r"tab\there".to_string()));
    }

    #[test]
    fn escaped_characters_in_single_quotes() {
        let content = "A='hello\\'world'\nB='back\\\\slash'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("A"), Some(&"hello\\'world".to_string()));
        assert_eq!(vars.get("B"), Some(&"back\\\\slash".to_string()));
    }

    #[test]
    fn quotes_embedded_in_middle_of_value() {
        let content = "A=hel\"lo\nB=hel'lo";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("A"), Some(&"hel\"lo".to_string()));
        assert_eq!(vars.get("B"), Some(&"hel'lo".to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes() {
        let content = r#"A="it's here""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("A"), Some(&"it's here".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes() {
        let content = r#"A='say "hello"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("A"), Some(&"say \"hello\"".to_string()));
    }

    #[test]
    fn inline_comment_is_included_in_value() {
        let content = "KEY=value # this is not stripped";
        let vars = EnvFileParser::parse(content).unwrap();
        // The parser does not strip inline comments
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is not stripped".to_string())
        );
    }

    #[test]
    fn whitespace_only_lines_are_skipped() {
        let content = "KEY1=a\n   \n\t\t\nKEY2=b";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 2);
        assert_eq!(vars.get("KEY1"), Some(&"a".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"b".to_string()));
    }

    #[test]
    fn tabs_around_key_and_value() {
        let content = "\tKEY\t=\tvalue\t";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn empty_key_with_equals_at_start() {
        let content = "=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"value".to_string()));
    }

    #[test]
    fn empty_content_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn content_with_only_comments_returns_empty_map() {
        let content = "# comment one\n# comment two\n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn multiple_equals_in_quoted_value() {
        let content = r#"CONN="host=localhost port=5432 dbname=test""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("CONN"),
            Some(&"host=localhost port=5432 dbname=test".to_string())
        );
    }

    #[test]
    fn quoted_value_preserves_inner_whitespace() {
        let content = "KEY=\"  spaces  \"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaces  ".to_string()));
    }

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn load_reads_file_from_disk() {
        let dir = tempfile::tempdir().unwrap();
        let file_path = dir.path().join(".env");
        std::fs::write(&file_path, "FROM_FILE=hello\nNUM=42").unwrap();

        let vars = EnvFileParser::load(&file_path).unwrap();
        assert_eq!(vars.get("FROM_FILE"), Some(&"hello".to_string()));
        assert_eq!(vars.get("NUM"), Some(&"42".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/path/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::tempdir().unwrap();
        let file_path = dir.path().join(".env");
        std::fs::write(&file_path, "OPT_KEY=present").unwrap();

        let vars = EnvFileParser::load_optional(&file_path).unwrap();
        assert_eq!(vars.get("OPT_KEY"), Some(&"present".to_string()));
    }

    #[test]
    fn value_with_unicode() {
        let content = "GREETING=\"\u{00e9}\u{00e0}\u{00fc}\"\nEMOJI=\u{1f680}";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"\u{00e9}\u{00e0}\u{00fc}".to_string()));
        assert_eq!(vars.get("EMOJI"), Some(&"\u{1f680}".to_string()));
    }

    #[test]
    fn value_with_trailing_backslash() {
        let content = r"KEY=path\to\dir\";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"path\to\dir\".to_string()));
    }

    #[test]
    fn key_with_underscores_and_numbers() {
        let content = "MY_VAR_2=works\n_LEADING=ok\nTRAILING_=ok";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("MY_VAR_2"), Some(&"works".to_string()));
        assert_eq!(vars.get("_LEADING"), Some(&"ok".to_string()));
        assert_eq!(vars.get("TRAILING_"), Some(&"ok".to_string()));
    }
}

